/**
 * Signals in message f_BmsState.
 *
 * foxBMS 2 (CC-BY-4.0); sent every 100 ms by the BMS emulator
 *
 * All signal values are as on the CAN bus.
 */
struct bms_can_f_bms_state_t {
    /**
     * Shows the number of connected strings, i.e., the strings in which the contactors are closed
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t number_of_connected_strings;

    /**
     * Shows the internal state of the BMS state machine
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_state;

    /**
     * Indicates whether cooling is active or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cooling_state;

    /**
     * Indicates whether the heater is active or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t heater_state;

    /**
     * Indicates whether the insulation monitoring device is active or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t insulation_monitoring;

    /**
     * Indicates whether a task has violated its timing requirements
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t system_monitoring_error;

    /**
     * Indicates that the BMS is preparing to open the contactors soon due to detected error
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t emergency_shutoff;

    /**
     * Indicates whether any error is present on the BMS or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t general_error;

    /**
     * Indicates whether any warning is present on the BMS or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t general_warning;

    /**
     * Indicates whether charging is completed or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t charging_complete;

    /**
     * Indicates whether an insulation error has been detected or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t insulation_error;

    /**
     * Indicates whether the is closed or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t interlock_state;

    /**
     * Indicates whether there is the main fuse is blown or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t main_fuse_blown;

    /**
     * Indicates whether a too low PCB temperature (i.e., undertemperature) of the BMS Master has been detected or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_master_pcb_undertemperature_erro;

    /**
     * Indicates whether a too high PCB temperature (i.e., overtemperature) of the BMS Master has been detected or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_master_pcb_overtemperature_error;

    /**
     * Indicates whether there is an MCU temperature error or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t mcu_die_temperature_error;

    /**
     * Indicates whether precharging was successful or needed to aborted because of a current limit violation
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t precharge_current_error;

    /**
     * Indicates whether precharging was successful or needed to aborted because of a too high voltage difference
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t precharge_voltage_error;

    /**
     * Indicates a possible error with Clamp 30C supply
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t clamp30c_error;

    /**
     * Indicates whether a CRC error has been detected in the NVRAM or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t nvram_crc_error;

    /**
     * Indicates whether any alter flag is set or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t alert_flag;

    /**
     * Indicates that the bms is charging
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_charging_flag;

    /**
     * Indicates whether a too high pack current (i.e., overcurrent) has been detected during discharging or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t pack_overcurrent_discharge_error;

    /**
     * Indicates whether a too high pack current (i.e., overcurrent) has been detected during charing or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t pack_overcurrent_charge_error;

    /**
     * Indicates if the selected balancing algorithm allows balancing. This indicates not if a cell is actually balanced or not. This is indicated in IsBalancingActive flag in f_StringState message
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t balancing_algorithm_state;

    /**
     * Indicates whether there is CAN timing error or not
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t can_timing_error;

    /**
     * Indicates that the phy hardware is reachable
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t phy_alive;

    /**
     * Range: 0..63 (0..63 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_substate;

    /**
     * Indicates that the phy has a network connection
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t phy_linked;

    /**
     * Shows the number of not connected strings, i.e., the strings in which the contactors are open
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t number_of_deactivated_strings;

    /**
     * Range: 0..255 (0..51000 kOhm)
     * Scale: 200
     * Offset: 0
     */
    uint8_t insulation_resistance;
};

/**
 * Signals in message f_PackLimits.
 *
 * foxBMS 2 (CC-BY-4.0); sent every 100 ms by the BMS emulator
 *
 * All signal values are as on the CAN bus.
 */
struct bms_can_f_pack_limits_t {
    /**
     * Maximum battery pack discharge current
     *
     * Range: 0..4095 (0..1023.75 A)
     * Scale: 0.25
     * Offset: 0
     */
    uint16_t maximum_discharge_current;

    /**
     * Maximum battery pack charge current
     *
     * Range: 0..4095 (0..1023.75 A)
     * Scale: 0.25
     * Offset: 0
     */
    uint16_t maximum_charge_current;

    /**
     * Maximum battery pack discharge power
     *
     * Range: 0..4095 (0..409.5 kW)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t maximum_discharge_power;

    /**
     * Maximum battery pack charge power
     *
     * Range: 0..4095 (0..409.5 kW)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t maximum_charge_power;

    /**
     * Maximum allowed battery pack voltage (defined by either cell limits or restricted by the charging algorithm)
     *
     * Range: 0..255 (0..1020 V)
     * Scale: 4
     * Offset: 0
     */
    uint8_t maximum_battery_voltage;

    /**
     * Minimum allowed battery pack voltage (defined by the cell limits or application specification)
     *
     * Range: 0..255 (0..1020 V)
     * Scale: 4
     * Offset: 0
     */
    uint8_t minimum_battery_voltage;
};

/**
 * Signals in message f_PackValuesP0.
 *
 * foxBMS 2 (CC-BY-4.0); sent every 100 ms by the BMS emulator
 *
 * All signal values are as on the CAN bus.
 */
struct bms_can_f_pack_values_p0_t {
    /**
     * Battery voltage between negative and positive pole of the battery
     *
     * Range: -16384..16383 (-1638.4..1638.3 V)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t battery_voltage;

    /**
     * Battery voltage between negative pole and after main positive contactor TODO
     *
     * Range: -16384..16383 (-1638.4..1638.3 V)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t bus_voltage;

    /**
     * Battery power
     *
     * Range: -65536..65535 (-655.36..655.35 kW)
     * Scale: 0.01
     * Offset: 0
     */
    int32_t power;

    /**
     * Battery pack current
     *
     * Range: -65536..65535 (-655.36..655.35 A)
     * Scale: 0.01
     * Offset: 0
     */
    int32_t current;
};

/**
 * Signals in message f_PackStateEstimation.
 *
 * foxBMS 2 (CC-BY-4.0); sent every 100 ms by the BMS emulator
 *
 * All signal values are as on the CAN bus.
 */
struct bms_can_f_pack_state_estimation_t {
    /**
     * Minimum SOC currently connected to HV bus (100% if all strings connected and all strings at 100%)
     *
     * Range: 0..1023 (0..102.3 %)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t minimum_soc;

    /**
     * Maximum SOC currently connected to HV bus (100% if all strings connected and all strings at 100%)
     *
     * Range: 0..1023 (0..102.3 %)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t maximum_soc;

    /**
     * Minimum SOE currently connected to HV bus (100% if all strings connected and all strings at 100%)
     *
     * Range: 0..1023 (0..102.3 %)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t minimum_soe;

    /**
     * Maximum SOE currently connected to HV bus (100% if all strings connected and all strings at 100%)
     *
     * Range: 0..1023 (0..102.3 %)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t maximum_soe;

    /**
     * Range: 0..255 (0..127.5 %)
     * Scale: 0.5
     * Offset: 0
     */
    uint8_t soh;

    /**
     * Energy left in Wh that is currently connected to HV bus
     *
     * Range: 0..65535 (0..6553.5 kWh)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t energy;
};

