/**
 * Signals in message ADV_Status.
 *
 * Advisory layer status (this project)
 *
 * All signal values are as on the CAN bus.
 */
struct bms_can_adv_status_t {
    /**
     * Increments every frame (wraps); stale if unchanged > 1 s
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t heartbeat;

    /**
     * 1 = estimates usable (initialised, inputs fresh)
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t valid;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t soc_valid;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t soh_valid;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t sop_valid;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t soe_valid;

    /**
     * 1 = BMS frames missing for longer than ADV_tStale
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t inputs_stale;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t initialising;

    /**
     * Which estimator variant is running (0 = coulomb counting)
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t estimator_set;

    /**
     * Age of the newest BMS measurement set used
     *
     * Range: 0..4095 (0..4095 ms)
     * Scale: 1
     * Offset: 0
     */
    uint16_t input_age;

    /**
     * foxBMS BmsState last received
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_state_echo;

    /**
     * BMS measurement sets missed since start (wraps)
     *
     * Range: 0..65535 (0..65535 -)
     * Scale: 1
     * Offset: 0
     */
    uint16_t frames_missed;
};

